    46  TcpOption TcpOptionBuilder::build() const
    47  {
    48          uint8_t recType = static_cast<uint8_t>(m_RecType);
    49          size_t optionSize = m_RecValueLen + 2*sizeof(uint8_t);
    50
    51          if (recType == (uint8_t)PCPP_TCPOPT_EOL || recType == (uint8_t)PCPP_TCPOPT_NOP)
    52          {
    53                  if (m_RecValueLen != 0)
    54                  {
    55                          PCPP_LOG_ERROR("TCP NOP and TCP EOL options are 1-byte long and don't have option value. Tried to set option value of size " << m_RecValueLen);
    56                          return TcpOption(nullptr);
    57                  }
    58
    59                  optionSize = 1;
    60          }
    61
    62          uint8_t* recordBuffer = new uint8_t[optionSize];
    63          memset(recordBuffer, 0, optionSize);
    64          recordBuffer[0] = recType;
    65          if (optionSize > 1)
    66          {
    67                  recordBuffer[1] = static_cast<uint8_t>(optionSize);
    68                  if (optionSize > 2 && m_RecValue != nullptr)
    69                          memcpy(recordBuffer+2, m_RecValue, m_RecValueLen);
    70          }
    71
    72          return TcpOption(recordBuffer);
    73  }
